//! `pin-refresh`: rewrites every World pin, its identity file and the preproduction manifest to the
//! values of the tree, so a stale or merge-conflicted pin is regenerated by one command instead of
//! copying the digests from two `pin-check` refusals by hand. Each pin keeps its reviewed
//! entry tile and expresses its floor as Global z. `pin-check` stays the gate that proves the result.

use std::fs;
use std::path::Path;

use oteryn_world_bundle_compiler::Error;
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use toml_edit::{DocumentMut, Item, Value as TomlValue};

use super::{
    PIN_SCHEMA, PINS, Pin, build_twice, derive_identity, hex, identity_text, inputs_digest, read,
};

/// The World whose bundle the preproduction topology manifest serves, and that manifest.
const PREPROD_MANIFEST: (&str, &str) = ("oteryn", "deploy/synology-game/preprod-topology.toml");

/// Refreshes every pin from the tree's staged inputs (`inputs_digest` reads the git index, so the
/// inputs are staged first). Returns the JSON summary.
pub(super) fn run(root: &Path) -> Result<Value, Error> {
    let pins = root.join(PINS);
    let manifest_path = root.join(PREPROD_MANIFEST.1);
    let tree = inputs_digest(root)?;
    let mut reports = Vec::new();
    for slug in super::pin_slugs(&pins)? {
        let fail = |what: String| Error::Format(format!("pin {slug}: {what}"));
        let path = pins.join(format!("{slug}.json"));
        let mut old: Value =
            serde_json::from_slice(&read(&path)?).map_err(|e| fail(e.to_string()))?;
        if old["schema"] == "OTERYN_WORLD_PIN/v1" {
            // Refresh is the migration path; pin-check accepts only v2.
            if let Some(fields) = old.as_object_mut() {
                fields.remove("inputs_digest");
            }
        } else if old["schema"] != PIN_SCHEMA {
            return Err(fail(format!("unsupported schema; expected {PIN_SCHEMA}")));
        }
        let old: Pin = serde_json::from_value(old).map_err(|e| fail(e.to_string()))?;
        let manifest = (slug == PREPROD_MANIFEST.0)
            .then(|| read_manifest(&manifest_path, &old))
            .transpose()?;
        let entry_start = super::EntryStart {
            floor: old
                .entry_start
                .floor
                .checked_abs()
                .filter(|floor| *floor <= 15)
                .ok_or_else(|| fail("entry_start: Global floor outside 0..15".into()))?,
            ..old.entry_start
        };
        let identity = derive_identity(root, &slug)?;
        let (bytes, registry) = build_twice(root, &identity)?;
        super::entry_start::check(&bytes, entry_start, &registry)?;
        let pin = Pin {
            schema: PIN_SCHEMA.to_owned(),
            digest: hex(&bytes[bytes.len() - 32..]),
            project_format_version: identity.project_format_version.clone(),
            world_schema_version: identity.world_schema_version.clone(),
            content_revision: identity.content_revision.clone(),
            production: false,
            entry_start,
        };
        let text = serde_json::to_string_pretty(&pin).map_err(|e| fail(e.to_string()))? + "\n";
        let manifest = manifest
            .map(|doc| refresh_manifest(&manifest_path, doc, &pin))
            .transpose()?;
        write(
            &pins.join(format!("{slug}.identity.json")),
            &identity_text(&identity)?,
        )?;
        write(&path, &text)?;
        if let Some(manifest) = manifest {
            write(&manifest_path, &manifest)?;
        }
        reports.push(json!({"world": slug, "digest": pin.digest, "previous": old.digest}));
    }
    let client_placements = refresh_client_placements(root)?;
    Ok(json!({"inputs_digest": tree, "pins": reports, "client_placements": client_placements}))
}

/// Points the manifest's `[world_bundle]` table and `[readiness] map_revision` at the new pin.
fn refresh_manifest(path: &Path, mut doc: DocumentMut, pin: &Pin) -> Result<String, Error> {
    for (table, key, mut value) in manifest_fields(pin) {
        let current = manifest_field_mut(path, &mut doc, table, key, &value)?;
        *value.decor_mut() = current.decor().clone();
        *current = value;
    }
    let output = doc.to_string();
    parse_manifest(path, &output)?;
    Ok(output)
}

fn read_manifest(path: &Path, pin: &Pin) -> Result<DocumentMut, Error> {
    let text =
        fs::read_to_string(path).map_err(|e| Error::Format(format!("{}: {e}", path.display())))?;
    let mut doc = parse_manifest(path, &text)?;
    for (table, key, value) in manifest_fields(pin) {
        manifest_field_mut(path, &mut doc, table, key, &value)?;
    }
    Ok(doc)
}

fn manifest_fields(pin: &Pin) -> [(&'static str, &'static str, TomlValue); 9] {
    let world = "world_bundle";
    [
        ("readiness", "map_revision", TomlValue::from(&pin.digest)),
        (world, "digest", TomlValue::from(&pin.digest)),
        (
            world,
            "project_format_version",
            TomlValue::from(&pin.project_format_version),
        ),
        (
            world,
            "world_schema_version",
            TomlValue::from(&pin.world_schema_version),
        ),
        (
            world,
            "content_revision",
            TomlValue::from(&pin.content_revision),
        ),
        (world, "production", TomlValue::from(pin.production)),
        (
            world,
            "start_x",
            TomlValue::from(i64::from(pin.entry_start.x)),
        ),
        (
            world,
            "start_y",
            TomlValue::from(i64::from(pin.entry_start.y)),
        ),
        (
            world,
            "start_floor",
            TomlValue::from(i64::from(pin.entry_start.floor)),
        ),
    ]
}

fn manifest_field_mut<'a>(
    path: &Path,
    doc: &'a mut DocumentMut,
    table: &str,
    key: &str,
    value: &TomlValue,
) -> Result<&'a mut TomlValue, Error> {
    doc.get_mut(table)
        .and_then(Item::as_table_mut)
        .and_then(|table| table.get_mut(key))
        .and_then(Item::as_value_mut)
        .filter(|current| current.type_name() == value.type_name())
        .ok_or_else(|| {
            Error::Format(format!(
                "{}: [{table}] {key} must be a TOML {}",
                path.display(),
                value.type_name()
            ))
        })
}

fn parse_manifest(path: &Path, text: &str) -> Result<DocumentMut, Error> {
    text.parse()
        .map_err(|e| Error::Format(format!("{}: {e}", path.display())))
}

/// The client reads the same immutable placement index as the World compiler.
/// Keep its source pin in the normal pin-refresh transaction after map edits.
fn refresh_client_placements(root: &Path) -> Result<Option<String>, Error> {
    let path = root.join("crates/client-assets/src/world.rs");
    // Small standalone World authoring fixtures need not contain a client crate.
    if !path.is_file() {
        return Ok(None);
    }
    let index = String::from_utf8(read(&root.join("content/world/placements/index.json"))?)
        .map_err(|_| Error::Format("client placement index is not UTF-8".into()))?;
    // Match client-assets::text_sha256 on both LF and CRLF checkouts.
    let digest = hex(&Sha256::digest(index.replace("\r\n", "\n").as_bytes()));
    let text = String::from_utf8(read(&path)?)
        .map_err(|_| Error::Format("client World pin is not UTF-8".into()))?;
    let updated = client_placement_pin_text(&text, &digest)?;
    if updated != text {
        write(&path, &updated)?;
    }
    Ok(Some(digest))
}

fn client_placement_pin_text(text: &str, digest: &str) -> Result<String, Error> {
    const MARKER: &str = "pub const PLACEMENT_INDEX_SHA256: &str =";
    let fail = || Error::Format("expected one 64-hex client placement index pin".into());
    let mut matches = text.match_indices(MARKER);
    let (start, _) = matches.next().ok_or_else(fail)?;
    if matches.next().is_some() {
        return Err(fail());
    }
    let tail = start + MARKER.len();
    let begin = tail + text[tail..].find('"').ok_or_else(fail)? + 1;
    let end = begin + text[begin..].find('"').ok_or_else(fail)?;
    if end - begin != 64 || !text[begin..end].bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err(fail());
    }
    let mut output = text.to_owned();
    output.replace_range(begin..end, digest);
    Ok(output)
}

fn write(path: &Path, text: &str) -> Result<(), Error> {
    fs::write(path, text).map_err(|e| Error::Format(format!("{}: {e}", path.display())))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn client_pin_refresh_preserves_other_pins_and_refuses_ambiguous_sources() -> Result<(), Error>
    {
        let source = format!(
            "pub const OTHER: &str = \"{}\";\npub const PLACEMENT_INDEX_SHA256: &str =\n    \"{}\";\n",
            "1".repeat(64),
            "2".repeat(64)
        );
        let updated = client_placement_pin_text(&source, &"3".repeat(64))?;
        assert_eq!(updated, source.replace(&"2".repeat(64), &"3".repeat(64)));
        assert!(client_placement_pin_text(&format!("{source}{source}"), &"3".repeat(64)).is_err());
        assert!(
            client_placement_pin_text(
                "pub const PLACEMENT_INDEX_SHA256: &str = \"bad\";",
                &"3".repeat(64)
            )
            .is_err()
        );
        Ok(())
    }
}
